from abc import ABCMeta, abstractmethod
import logging
import os
import six
from taf.internal.core import NamedGroup, NamedObject
from .collectable import CollectableComponentBase, CollectableObjectBase, CollectableGroupBase
from collections import deque

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class AsyncCollectableComponent(CollectableComponentBase):
    """
    An object, that can asynchronously collect information from source locations.

    A asynchronously collectable component can either be a single collectable object
    or a group of collectable components.

    Examples for source locations are files in the filesystem of a remote host, local files in another
    directory than the target_dir or information retrievable via HTTP.

    """

    def async_collect(self, target_dir, _first=True):
        """
        Asynchronously collect information from source locations.

        Each collector component creates an own subdirectory below target_dir.

        If this object has collected the information already during the same user-initiated async_collect() call,
        don't collect the information again.

        :param str target_dir:
            Target directory, where collected information shall be stored on the local host,
            Multiple user-initiated calls of async_collect() on the same async collectable component must use different
            values for target_dir to avoid overwriting previously collected files.
        :param boolean _first:
            internal flag to distinguish the user-initiated async_collect() call from resulting internal
            async_collect() calls
        """
        target_dir = os.path.join(target_dir, self._name)
        self._create_dir(path=target_dir)
        awaitables = self._do_async_collect(target_dir=target_dir)
        if _first:
            self._clear_has_collected()
        return awaitables

    @staticmethod
    def wait(awaitables_list):
        """
        Wait for one or more async_collect() operation(s) to finish.

        :param list(GeneratorType) awaitables_list:
            list of objects returned from async_collect() calls
        """
        awaitables = deque(awaitables_list)
        while awaitables:
            awaitable = awaitables[0]
            try:
                next(awaitable)
            except StopIteration:
                awaitables.popleft()
            else:
                awaitables.append(awaitables.popleft())

    @abstractmethod
    def _do_async_collect(self, target_dir):
        """
        Asynchronously collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """


@six.add_metaclass(ABCMeta)
class AsyncCollectableObject(CollectableObjectBase, NamedObject, AsyncCollectableComponent):
    """
    Asynchronous Collectable object.
    """

    def _do_async_collect(self, target_dir):
        """
        Asynchronously collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """
        if not self._has_collected:
            awaitables = self._async_collect(target_dir=target_dir)
            self._has_collected = True
            return awaitables
        else:
            return []

    @abstractmethod
    def _async_collect(self, target_dir):
        """
        Asynchronously collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """


class AsyncCollectableGroup(CollectableGroupBase, NamedGroup, AsyncCollectableComponent):
    """
    Group of async collectable components.
    """

    def _do_async_collect(self, target_dir):
        """
        Asynchronously collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """
        return sum(
            (
                member.async_collect(target_dir=target_dir, _first=False)
                for member in self._members),
            [])
